#!/usr/bin/env python3
"""Summarize matched baseline/current JMH rows without mixing workload parameters."""
# Copyright (c) 2026 Eclipse RDF4J contributors.
# SPDX-License-Identifier: BSD-3-Clause
# Some portions generated by Codex
import json
from pathlib import Path
import statistics
import sys

pairs = {}
for filename in sys.argv[1:]:
    for row in json.loads(Path(filename).read_text()):
        params = row["params"]
        implementation = params["implementation"]
        if implementation not in {"baseline", "current"}:
            continue
        key = (params["workload"], params["sink"], params["namespaceLayout"])
        pair = pairs.setdefault(key, {})
        if implementation in pair:
            raise ValueError(f"Duplicate measurement for {key}: {implementation}")
        primary = row["primaryMetric"]
        allocation = row["secondaryMetrics"]["gc.alloc.rate.norm"]
        if primary["scoreUnit"] != "ns/op" or allocation["scoreUnit"] != "B/op":
            raise ValueError("Expected time in ns/row and allocation in B/row")
        pair[implementation] = {
            "ns_per_row": primary["score"],
            "ns_error_99_9_percent": primary["scoreError"],
            "ns_confidence_interval": primary["scoreConfidence"],
            "bytes_per_row": allocation["score"],
            "bytes_error_99_9_percent": allocation["scoreError"],
            "ns_per_row_by_fork": [statistics.mean(fork) for fork in primary["rawData"]],
            "bytes_per_row_by_fork": [statistics.mean(fork) for fork in allocation["rawData"]],
            "source": str(filename),
        }
results = []
print("| Workload | Sink | Main µs/row | Patched µs/row | Speedup | Main B/row | Patched B/row |")
print("| --- | --- | ---: | ---: | ---: | ---: | ---: |")
for (workload, sink, namespace), pair in pairs.items():
    before, after = pair["baseline"], pair["current"]
    speedup = before["ns_per_row"] / after["ns_per_row"]
    item = {"workload": workload, "sink": sink, "namespaceLayout": namespace, **pair,
            "speedup": speedup,
            "time_reduction_percent": 100 * (1 - 1 / speedup),
            "allocation_reduction_percent": 100 * (1 - after["bytes_per_row"] / before["bytes_per_row"])}
    results.append(item)
    print(f"| {workload} | {sink} | {before['ns_per_row']/1000:.3f} ± {before['ns_error_99_9_percent']/1000:.3f} | "
          f"{after['ns_per_row']/1000:.3f} ± {after['ns_error_99_9_percent']/1000:.3f} | {speedup:.2f}× | "
          f"{before['bytes_per_row']:.2f} | {after['bytes_per_row']:.2f} |")
Path(__file__).resolve().parent.parent.joinpath("comparison-summary.json").write_text(json.dumps(results, indent=2) + "\n")
